class CompositeComponentRow(TimestampMixin, Base):
    """One row of a sub-detail.

    A single wide table with nullable columns keyed by ``component_type`` keeps
    the sub-detail readable in one query. Which columns are required for which
    type is validated in :mod:`metreo_api.services.composites`, and the
    check constraint below stops an unknown type from being stored at all.
    """

    __tablename__ = "composite_components"
    __table_args__ = (
        # Frontière multi-tenant tenue par la base : l'enfant ne peut pointer
        # qu'un parent de SA propre organisation. L'action référentielle reflète
        # celle de la clé simple que double chaque composite — sans ce reflet, le
        # résultat d'une suppression dépendrait de l'ordre de création des
        # contraintes (révision `b4f2c7d81a05`).
        ForeignKeyConstraint(
            ["composite_price_id", "organization_id"],
            ["composite_prices.id", "composite_prices.organization_id"],
            name="fk_composite_components_composite_price_tenant",
            ondelete="CASCADE",
        ),
        # Frontière multi-tenant tenue par la base : l'enfant ne peut pointer
        # qu'un parent de SA propre organisation. L'action référentielle de ces
        # clés composites appartient aux migrations et non aux modèles : elle
        # diffère d'un moteur à l'autre. Sur PostgreSQL, la révision
        # `b4f2c7d81a05` fait refléter à chaque composite l'action de la clé
        # simple qu'elle double — `SET NULL (colonne_enfant)` plutôt qu'un
        # `SET NULL` nu, qui viderait aussi `organization_id`, NOT NULL — afin
        # que le résultat d'une suppression ne dépende plus de l'ordre de
        # création des contraintes. SQLite n'en a pas besoin : mesuré, les deux
        # ordres y donnent le même résultat.
        ForeignKeyConstraint(
            ["price_item_id", "organization_id"],
            ["price_items.id", "price_items.organization_id"],
            name="fk_composite_components_price_item_tenant",
            ondelete="SET NULL (price_item_id)",
        ),
        CheckConstraint(
            "component_type IN ('consumption','output_rate','rotation','lump_sum')",
            name="ck_composite_component_type",
        ),
    )

    id: Mapped[str] = mapped_column(String(36), primary_key=True, default=new_id)
