    label: Mapped[str] = mapped_column(String(255), nullable=False)
    resource_kind: Mapped[str] = mapped_column(String(30), nullable=False, default="other")
    price_item_id: Mapped[str | None] = mapped_column(
        String(36), ForeignKey("price_items.id", ondelete="SET NULL")
    )

    # consumption
    consumption: Mapped[Decimal | None] = mapped_column(Amount)
    resource_unit_code: Mapped[str | None] = mapped_column(String(12))
    unit_price: Mapped[Decimal | None] = mapped_column(Amount)
