class EstimateVersion(TimestampMixin, Base):
    """A frozen version stores the computed result *and* its inputs.

    ``snapshot`` holds the resolved lines, the price book version identifier,
    the markup policy and the tax rates that were in force. Recomputing it later
    reproduces the same numbers even if the library has moved on, which is what
    acceptance scenarios 6 and 7 require.
    """

    __tablename__ = "estimate_versions"
    __table_args__ = (
        # Frontière multi-tenant tenue par la base : l'enfant ne peut pointer
        # qu'un parent de SA propre organisation. L'action référentielle reflète
        # celle de la clé simple que double chaque composite — sans ce reflet, le
        # résultat d'une suppression dépendrait de l'ordre de création des
        # contraintes (révision `b4f2c7d81a05`).
        ForeignKeyConstraint(
            ["estimate_id", "organization_id"],
            ["estimates.id", "estimates.organization_id"],
            name="fk_estimate_versions_estimate_tenant",
            ondelete="CASCADE",
        ),
        ForeignKeyConstraint(
            ["price_book_version_id", "organization_id"],
            ["price_book_versions.id", "price_book_versions.organization_id"],
            name="fk_estimate_versions_price_book_version_tenant",
        ),
        UniqueConstraint("estimate_id", "version_number", name="uq_estimateversion_number"),
        CheckConstraint(
            "status IN ('draft','frozen','superseded')", name="ck_estimate_version_status"
        ),
    )

    id: Mapped[str] = mapped_column(String(36), primary_key=True, default=new_id)
    organization_id: Mapped[str] = mapped_column(
        String(36), ForeignKey("organizations.id", ondelete="CASCADE"), nullable=False, index=True
    )
    estimate_id: Mapped[str] = mapped_column(
        String(36), ForeignKey("estimates.id", ondelete="CASCADE"), nullable=False, index=True
    )
    version_number: Mapped[int] = mapped_column(Integer, nullable=False, default=1)
    label: Mapped[str | None] = mapped_column(String(200))
    status: Mapped[str] = mapped_column(String(20), nullable=False, default="draft")
    price_book_version_id: Mapped[str] = mapped_column(
        String(36), ForeignKey("price_book_versions.id"), nullable=False
    )
    markup: Mapped[dict] = mapped_column(SAJSON, nullable=False, default=dict)
    taxes: Mapped[list] = mapped_column(SAJSON, nullable=False, default=list)
    rounding: Mapped[dict] = mapped_column(SAJSON, nullable=False, default=dict)
    missing_price_policy: Mapped[str] = mapped_column(String(10), nullable=False, default="block")
    snapshot: Mapped[dict | None] = mapped_column(SAJSON)
    snapshot_sha256: Mapped[str | None] = mapped_column(String(64))
    #: Totaux **bruts**, non arrondis, tels que le moteur les a produits. Ce
    #: sont eux qui servent aux calculs internes et aux comparaisons ; ils ne
    #: sont pas ce que le devis imprime.
    total_selling_price_ht: Mapped[Decimal | None] = mapped_column(Amount)
    total_ttc: Mapped[Decimal | None] = mapped_column(Amount)
    #: Totaux **du document**, figés au gel : exactement les nombres que le
    #: devis remis au client porte, sous la convention « le document
    #: s'additionne » (voir `docs/ARRONDI_DES_DOCUMENTS.md`).
    #:
    #: Deux colonnes distinctes plutôt qu'une réinterprétation des précédentes :
    #: brut et imprimé ne coïncident pas, et une colonne qui aurait porté les
    #: deux sens selon la date de la ligne aurait été un piège permanent.
    #:
    #: `NULL` a un sens précis et unique : *le total documentaire de cette
    #: version gelée n'a pas pu être reconstruit*. Il n'est jamais remplacé en
    #: silence par l'arrondi du brut — un lecteur doit savoir qu'il ne dispose
    #: pas du nombre imprimé. Une version brouillon n'en porte pas non plus :
    #: son document se recalcule à la demande.
    document_total_ht: Mapped[Decimal | None] = mapped_column(Amount)
    document_total_ttc: Mapped[Decimal | None] = mapped_column(Amount)
    frozen_at: Mapped[datetime | None] = mapped_column(DateTime)
    frozen_by: Mapped[str | None] = mapped_column(String(36), ForeignKey("users.id"))
    created_by: Mapped[str | None] = mapped_column(String(36), ForeignKey("users.id"))


# --------------------------------------------------------------------------
# Audit
# --------------------------------------------------------------------------


class AuditEvent(Base):
    """Append-only journal with a per-organisation hash chain.

    ``previous_hash`` links each row to the one before it inside the same
    organisation. Deleting or editing a row breaks the chain, which
    ``/audit/verify`` detects. This is tamper-evidence, not tamper-proofing —
    stated as such in the security threat model.
    """

    __tablename__ = "audit_events"
    __table_args__ = (
        Index("ix_audit_org_occurred", "organization_id", "occurred_at"),
        UniqueConstraint("organization_id", "sequence", name="uq_audit_org_sequence"),
    )

    id: Mapped[str] = mapped_column(String(36), primary_key=True, default=new_id)
    organization_id: Mapped[str] = mapped_column(
        String(36), ForeignKey("organizations.id", ondelete="CASCADE"), nullable=False, index=True
    )
    sequence: Mapped[int] = mapped_column(Integer, nullable=False)
    occurred_at: Mapped[datetime] = mapped_column(DateTime, nullable=False, default=utcnow)
    actor_user_id: Mapped[str | None] = mapped_column(String(36))
    actor_email: Mapped[str | None] = mapped_column(String(255))
    action: Mapped[str] = mapped_column(String(80), nullable=False)
    object_type: Mapped[str] = mapped_column(String(60), nullable=False)
    object_id: Mapped[str | None] = mapped_column(String(36))
    summary: Mapped[str] = mapped_column(Text, nullable=False)
    payload: Mapped[dict] = mapped_column(SAJSON, nullable=False, default=dict)
    request_id: Mapped[str | None] = mapped_column(String(64))
    #: Version du schéma de hash sous laquelle l'événement a été scellé. Une
    #: constante Python seule ne permettrait pas de revérifier durablement des
    #: événements créés sous plusieurs versions : la vérification lirait le code
    #: d'aujourd'hui pour juger un scellé d'hier.
    #: Renseigné explicitement par `audit.record()`. Pas de valeur par défaut :
    #: un défaut silencieux à 1 marquerait un événement scellé en v2 comme v1,
    #: et le rendrait invérifiable.
    hash_schema_version: Mapped[int] = mapped_column(Integer, nullable=False)
    previous_hash: Mapped[str | None] = mapped_column(String(64))
    hash: Mapped[str] = mapped_column(String(64), nullable=False)
